import assert from "node:assert/strict";
import { readFileSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { posix } from "node:path";
import { pathToFileURL } from "node:url";

const snapshot = JSON.parse(readFileSync(process.env.COVERAGE_SNAPSHOT ?? "/tmp/safe-bash-command-inventory-snapshot.json"));
const root = snapshot.directory;
const load = relative => import(pathToFileURL(`${root}/${relative}`).href);
const ours = await load("src/index.ts");
const baseline = await load("benchmarks/node_modules/just-bash/dist/bundle/index.js");
const { parseFixtures, deterministicCases, probes } = await load("benchmarks/fixtures.ts");
const { pluginFixtures } = await load("benchmarks/plugin-fixtures.ts");
const { dialectFixtures } = await load("benchmarks/dialect-fixtures.ts");
const digest = value => createHash("sha256").update(value).digest("hex");
const comparatorPackage = JSON.parse(readFileSync(`${root}/benchmarks/node_modules/just-bash/package.json`));
assert.equal(comparatorPackage.version, "3.4.2");
const definitions = ours.createAgentCommands();
const plugins = definitions.map(entry => entry.name).sort();
const optional = ours.createSafeJsCommands().map(entry => entry.name).sort();
const runtime = readFileSync(`${root}/src/shell/runtime.ts`, "utf8");
const builtinBody = runtime.slice(runtime.indexOf("async builtin("), runtime.indexOf("async part("));
const kernelBuiltins = [...new Set([...builtinBody.matchAll(/command === "([^"]+)"/g)].map(match => match[1]))].sort();
const classifiedBuiltins = JSON.parse(`[${runtime.match(/const shellBuiltinNames = new Set\(\[([\s\S]*?)\]\)/)[1].replace(/,\s*$/, "")}]`).sort();
const bundle = readFileSync(`${root}/benchmarks/node_modules/just-bash/dist/bundle/index.js`, "utf8");
const builtinSet = [...bundle.matchAll(/new Set\(\[([^\]]{1,20000})\]\)/g)].find(match => match[1].includes('"cd"') && match[1].includes('"eval"'));
assert.ok(builtinSet);
const baselineBuiltins = JSON.parse(`[${builtinSet[1]}]`).sort();
const dispatchPosition = bundle.indexOf('if(t==="cd")');
assert.ok(dispatchPosition > 0);
const dispatchBody = bundle.slice(bundle.lastIndexOf("async function ", dispatchPosition), bundle.indexOf("async function ", dispatchPosition));
const baselineKernel = [...new Set([...dispatchBody.matchAll(/t==="([^"]+)"/g)].map(match => match[1]))].filter(name => !name.startsWith("__just_bash_")).sort();
const baselineRegistry = baseline.getCommandNames().sort();
assert.deepEqual([...new baseline.Bash().commands.keys()].sort(), baselineRegistry);
const union = (...lists) => [...new Set(lists.flat())].sort();
const supported = union(plugins, kernelBuiltins);
const baselineSupported = union(baselineRegistry, baselineKernel);
const baselineRecognized = union(baselineRegistry, baselineBuiltins);
const recognitionOnly = baselineBuiltins.filter(name => !baselineSupported.includes(name));
const commonEnvironment = { PATH: "/usr/bin:/bin", LANG: "C", LC_ALL: "C", TZ: "UTC" };

async function prepare(engine, files, env, events) {
  const fs = engine === "virtual-bash" ? ours.createMemoryFileSystem() : new baseline.InMemoryFs();
  await fs.mkdir("/fixture", { recursive: true });
  for (const [name, bytes] of Object.entries(files)) {
    await fs.mkdir(posix.dirname(`/fixture/${name}`), { recursive: true });
    await fs.writeFile(`/fixture/${name}`, Buffer.from(bytes, "base64"));
    await fs.chmod(`/fixture/${name}`, name.endsWith(".sh") ? 0o755 : 0o644);
  }
  const environment = { ...commonEnvironment, ...env };
  if (engine === "virtual-bash") {
    const shell = new ours.Shell({ fs, cwd: "/fixture", env: environment,
      limits: { maxOutputBytes: 4 * 1024 * 1024, maxCommands: 10000, maxLoopIterations: 10000 } })
      .use(ours.agentCommands()).use(async (context, next) => {
        events.push({ command: context.command, args: [...context.args], kind: "middleware-dispatch" });
        return next();
      });
    await shell.exec("");
    return { fs, shell, async exec(source, stdin) {
      const result = await shell.exec(source, { stdin, signal: AbortSignal.timeout(4500) });
      return { stdout: Buffer.from(result.stdoutBytes).toString("base64"), stderr: Buffer.from(result.stderrBytes).toString("base64"), exitCode: result.exitCode };
    }, dispose: () => shell.dispose() };
  }
  const shell = new baseline.Bash({ fs, cwd: "/fixture", env: environment,
    executionLimits: { maxOutputSize: 4 * 1024 * 1024, maxCommandCount: 10000, maxLoopIterations: 10000, maxExecutionTimeMs: 4500 },
  });
  for (const [name, command] of shell.commands) {
    const execute = command.execute;
    shell.commands.set(name, { ...command, execute: (...args) => {
      events.push({ command: name, args: [...args[0]], kind: "registry-execute" });
      return execute(...args);
    } });
  }
  return { fs, shell, async exec(source, stdin) {
    const result = await shell.exec(source, { stdin: Buffer.from(stdin).toString("latin1"), stdinKind: "bytes", rawScript: true,
      replaceEnv: true, env: environment, signal: AbortSignal.timeout(4500) });
    return { stdout: Buffer.from(baseline.stdoutAsBytes(result)).toString("base64"), stderr: Buffer.from(result.stderr).toString("base64"), exitCode: result.exitCode };
  }, async dispose() {} };
}

const corpus = parseFixtures(readFileSync(`${root}/tests/fixtures/shell-cases.json`, "utf8"));
const fixtures = [...corpus, ...deterministicCases(1526603814), ...pluginFixtures(), ...dialectFixtures()];
const coverage = [];
for (const fixture of fixtures) {
  const row = { name: fixture.name, source: fixture.source, tags: fixture.tags, script: fixture.script, stdin: fixture.stdin, initialFiles: fixture.initialFiles, env: fixture.env, expected: fixture.expected, engines: {} };
  for (const engine of ["virtual-bash", "just-bash"]) {
    const events = [];
    const context = await prepare(engine, fixture.initialFiles, fixture.env, events);
    try {
      const observed = await context.exec(fixture.script, Buffer.from(fixture.stdin, "base64"));
      row.engines[engine] = { commands: union(events.map(event => event.command)), events,
        observed, streamsAndStatusMatchExpected: observed.stdout === fixture.expected.stdout && observed.stderr === fixture.expected.stderr && observed.exitCode === fixture.expected.exitCode };
    } catch (error) {
      row.engines[engine] = { commands: union(events.map(event => event.command)), events, error: String(error) };
    } finally { await context.dispose(); }
  }
  coverage.push(row);
}

const texts = {
  "script.sh": '#!/bin/bash\nprintf "%s\\n" "$1"\nprintf file > /fixture/script.out\n',
  "env.sh": 'VALUE=loaded\nprintf sourced > /fixture/source.out\n',
};
const scriptFiles = Object.fromEntries(Object.entries(texts).map(([name, text]) => [name, Buffer.from(text).toString("base64")]));
const highValueInputs = [
  ["bash-c", "bash -c 'printf \"%s\\n\" \"$1\"' shell argument", ""],
  ["sh-c", "sh -c 'printf \"%s\\n\" \"$1\"' shell argument", ""],
  ["bash-file", "bash /fixture/script.sh argument", ""],
  ["sh-file", "sh /fixture/script.sh argument", ""],
  ["bash-stdin", "bash -s -- argument", 'printf "%s\\n" "$1"\n'],
  ["bash-stdin-no-options", "bash", 'printf stdin-bash\n'],
  ["sh-stdin-no-options", "sh", 'printf stdin-sh\n'],
  ["sh-stdin-option", "sh -s -- argument", 'printf "%s\\n" "$1"\n'],
  ["source-file", 'source /fixture/env.sh && printf "%s\\n" "$VALUE"', ""],
  ["dot-file", '. /fixture/env.sh && printf "%s\\n" "$VALUE"', ""],
  ["eval-source", "eval 'printf evaluated'", ""],
  ["relative-executable-script", "./script.sh argument", ""],
  ["absolute-executable-script", "/fixture/script.sh argument", ""],
  ["path-executable-script", 'PATH="/fixture:$PATH"; script.sh argument', ""],
  ["command-bypass", "command printf command", ""],
  ["builtin-dispatch", "builtin printf builtin", ""],
  ["errexit-option", "set -e; false; printf SHOULD-NOT-RUN", ""],
  ["nounset-option", 'set -u; printf "%s" "$absent"', ""],
  ["read-array-option", "read -a fields", "a b\n"],
];
const scriptExecution = [];
for (const [name, script, stdin] of highValueInputs) {
  const row = { name, script, stdin: Buffer.from(stdin).toString("base64"), engines: {} };
  for (const engine of ["virtual-bash", "just-bash"]) {
    const context = await prepare(engine, scriptFiles, {}, []);
    try {
      const result = await context.exec(script, Buffer.from(stdin));
      const effects = {};
      for (const file of ["script.out", "source.out"]) {
        try { effects[file] = Buffer.from(engine === "virtual-bash" ? await context.fs.readFile(`/fixture/${file}`) : await context.fs.readFileBuffer(`/fixture/${file}`)).toString("base64"); }
        catch (error) { if (!(error && (error.code === "ENOENT" || /ENOENT|No such file/.test(String(error))))) throw error; }
      }
      row.engines[engine] = { ...result, stdoutText: Buffer.from(result.stdout,"base64").toString(), stderrText: Buffer.from(result.stderr,"base64").toString(), effects };
    } catch (error) { row.engines[engine] = { error: String(error) }; }
    finally { await context.dispose(); }
  }
  scriptExecution.push(row);
}

const coreDoc = readFileSync(`${root}/src/commands/README.md`,"utf8");
const declaredOptions = Object.fromEntries([...coreDoc.matchAll(/^\| `([^`]+)` \| (.+) \|$/gm)].map(match=>[match[1],match[2]]));
const recognitionOnlyProbes = [];
for (const name of recognitionOnly) {
  const context = await prepare("just-bash", {}, {}, []);
  try { recognitionOnlyProbes.push({ name, script: name, ...await context.exec(name, new Uint8Array()) }); }
  finally { await context.dispose(); }
}
const entries = union(supported,optional,baselineRecognized,baseline.getNetworkCommandNames(),baseline.getPythonCommandNames(),baseline.getJavaScriptCommandNames()).map(name=>({
  name,
  ours: { plugin: plugins.includes(name), kernelBuiltin: kernelBuiltins.includes(name), builtinClassified: classifiedBuiltins.includes(name),
    optional: optional.includes(name), status: supported.includes(name) ? "present; selected semantics, full option parity not established" : optional.includes(name) ? "optional injected runtime required" : "missing command name in inspected implementation",
    declaredOptions: declaredOptions[name]??null, fullOptionParityEstablished: false,
    cases: coverage.filter(row=>row.engines["virtual-bash"].commands.includes(name)).map(row=>row.name),
  },
  justBash: { registered: baselineRegistry.includes(name), builtinClassified: baselineBuiltins.includes(name), kernelBuiltin: baselineKernel.includes(name), recognitionOnly: recognitionOnly.includes(name),
    optional: baseline.getNetworkCommandNames().includes(name)?"network":baseline.getPythonCommandNames().includes(name)?"python":baseline.getJavaScriptCommandNames().includes(name)?"javascript":null,
    fullOptionParityAudited: false, cases: coverage.filter(row=>row.engines["just-bash"].commands.includes(name)).map(row=>row.name) },
}));
const recommendations = [
  { rank: 1, increment: "Virtual bash/sh and executable script dispatch", names: ["bash","sh"], rationale: "Run existing setup/build snippets, file scripts and stdin scripts inside the virtual runtime; preserve args, cwd, env, budgets and cancellation, without native spawning." },
  { rank: 2, increment: "Current-shell source/dot and bounded eval", names: ["source",".","eval"], rationale: "Load environment/helper scripts and compose shell snippets with correct caller state and positional restoration; eval must reuse the shell parser, never host JS." },
  { rank: 3, increment: "Shell fail-fast, discovery and cleanup controls", names: ["command","builtin","type","trap"], rationale: "Common scripts need set -e/-u, command discovery/bypass and cleanup after failure; complete execution semantics before adding more utility names." },
  { rank: 4, increment: "Metadata and permission workflows", names: ["stat","chmod","umask"], rationale: "Inspect sizes/modes and prepare executable scripts; adapters must expose truthful permission capability and errors, not fake chmod success." },
  { rank: 5, increment: "Safe temporary paths", names: ["mktemp"], rationale: "Coding workflows stage files and patches; atomic/exclusive creation, shared mounts and cleanup matter. This name is absent from both inspected default inventories." },
  { rank: 6, increment: "Bounded archive creation and extraction", names: ["tar"], rationale: "Move source/artifact trees through filesystems; defend paths, links and decompression quotas and test real backend effects." },
  { rank: 7, increment: "Text comparison and tabular composition", names: ["comm","join","paste","nl","tac"], rationale: "Compare manifests, combine columns and inspect numbered/reversed output without inventing complex awk programs." },
  { rank: 8, increment: "Portable scalar and environment helpers", names: ["seq","expr","printenv"], rationale: "Many shell snippets use range generation, scalar expressions and explicit environment inspection; keep locale and overflow behavior explicit." },
  { rank: 9, increment: "Time and bounded waiting", names: ["date","sleep","timeout"], rationale: "Timestamp artifacts and bound retry/wait loops using injectable clocks and cancellation rather than uncontrolled host work." },
  { rank: 10, increment: "Explicitly authorized HTTP client", names: ["curl"], rationale: "Fetch coding artifacts and call APIs with injected network policy, redirect/size/time limits and no ambient credentials; default-deny, not automatic network access." },
];
const report = {
  schemaVersion:1, createdAt:new Date().toISOString(), snapshot, node:process.version,
  comparator:{version:comparatorPackage.version,registrySource:"installed getCommandNames() and Bash.commands",builtinSource:"installed dist/bundle/index.js recognized builtin Set",bundleSha256:digest(bundle)},
  inventories:{ours:{plugins,kernelBuiltins,classifiedBuiltins,pluginBackedBuiltinNames:classifiedBuiltins.filter(name=>!kernelBuiltins.includes(name)),pluginNamesShadowedByKernel:plugins.filter(name=>kernelBuiltins.includes(name)),uniqueDefault:supported,optionalSafeJS:optional},justBash:{registered:baselineRegistry,builtinClassified:baselineBuiltins,kernelBuiltins:baselineKernel,recognitionOnly,recognizedDefault:baselineRecognized,uniqueDefault:baselineSupported,optional:{network:baseline.getNetworkCommandNames(),python:baseline.getPythonCommandNames(),javascript:baseline.getJavaScriptCommandNames()}}},
  coverageMethod:{fixtureCount:fixtures.length,oracleCount:corpus.length,comparativeTaskCount:fixtures.length+probes.length,seed:1526603814,
    ours:"Actual middleware dispatch, including kernel builtins and nested command invocation",justBash:"Actual registered execute calls only; builtin-only dispatch is not measured because enabling the coverage callback caused a loader/defense-in-depth interaction. No callback is enabled in this run.",assertions:"Only stdout/stderr/status observed here, not full filesystem comparator rerun; failed/partial executions still retain traced names. Script probes additionally record two exact effect files.",
    builtinCoverageLimit:"Recognized builtin names can be partial/stubbed; classification does not establish all option semantics. No universal full-support label is inferred.",
    stressProbes:probes.map(probe=>({name:probe.name,coverage:"source-inspected, not rerun for inventory",names:probe.name==="concurrent-pipelines"?["printf","cat"]:probe.name==="cooperative-cancellation"?["bench_wait"]:["bench_producer","bench_consumer"]}))},
  entries,fixtures:coverage,scriptExecution,scriptInitialFiles:scriptFiles,scriptFileModes:{"script.sh":"0755","env.sh":"0755"},recognitionOnlyProbes,recommendations,
  priorityBasis:"Judgment from missing basic coding workflows and observed feature gaps, NOT measured agent usage or popularity",
  fullOptions:{classification:"partial or unverified for both engines; no full native parity audit",documentedCoreOptions:declaredOptions},
  claims:{superiority:false,allFlagsCovered:false,completeShell:false,realProviderCoverage:false,installedDependencies:false,implementationChanged:false},
};
writeFileSync(process.env.COVERAGE_OUTPUT ?? "/Users/kjopek/Workspace/safe-bash/benchmarks/reports/COMMAND_COVERAGE.json",JSON.stringify(report,null,2)+"\n");
console.log(JSON.stringify({snapshot:snapshot.revision,oursPlugins:plugins.length,oursKernelBuiltins:kernelBuiltins.length,oursUnique:supported.length,justBashRegistry:baselineRegistry.length,justBashBuiltins:baselineBuiltins.length,justBashUnique:baselineSupported.length,fixtures:fixtures.length,coveredOursPluginNames:entries.filter(entry=>entry.ours.plugin&&entry.ours.cases.length).map(entry=>entry.name),uncoveredOurs:entries.filter(entry=>supported.includes(entry.name)&&!entry.ours.cases.length).map(entry=>entry.name),uncoveredBaseline:entries.filter(entry=>baselineSupported.includes(entry.name)&&!entry.justBash.cases.length).map(entry=>entry.name),probeResults:scriptExecution.map(row=>({name:row.name,ours:row.engines["virtual-bash"],justBash:row.engines["just-bash"]}))}));
